package com.friendai

import java.util.Locale
import com.momcompanion.ai.HandlersB

import android.content.Context
import java.util.Date


class CompanionEngine {

    companion object {
        /**
         * If Mom opens with any of these, skip the once-a-day wellbeing check-in and let her
         * actual request/topic be answered directly instead. (Replaces a ~150-level-deep nested
         * if/else chain that did the same string-contains checks one at a time.)
         */
        private val CHECKIN_SKIP_KEYWORDS = listOf(
            // greetings — let the greeting handler fire instead of the check-in
            "how are you", "как дела", "hello", "hi", "hey", "привет", "здравствуйте",
            "доброе утро", "добрый день", "добрый вечер", "good morning", "good afternoon", "good evening",
            // entertainment requests
            "story", "joke", "poem", "рассказ", "шутка", "стих", "анекдот", "сказка",
            "music", "song", "sing", "музыка", "песня", "спой",
            // questions and help
            "repeat", "help", "what can you do", "question", "вопрос",
            // safety / urgency
            "emergency", "chest pain", "i fell", "can't breathe", "боль", "упала",
            // communication
            "bye", "goodbye", "пока", "до свидания", "спокойной ночи", "good night",
            // health / daily needs
            "remind", "appointment", "medication", "hydrate", "water", "food",
            "eat", "drink", "hungry", "thirsty", "голодна", "хочу пить", "лекарство",
            // people / contact
            "caregiver", "family", "doctor", "call", "phone", "contact",
            "помощник", "семья", "врач", "позвони",
            // memory / reminiscing
            "i remember", "я помню", "помню как", "раньше", "в детстве",
            // emotional openers — handle these directly
            "i'm sad", "i'm lonely", "i'm scared", "i'm bored", "i'm angry",
            "грустно", "одиноко", "страшно", "скучно", "злюсь",
            // settings / technical (skip check-in for these always)
            "settings", "test", "token", "backend", "pin", "profile",
            "vocabulary", "topic", "rule", "rules", "privacy", "notice", "save",
            "ok", "okay", "yes", "no", "cancel", "done", "next", "back", "home",
            "main", "screen", "activity", "button", "input", "text", "view",
            "layout", "android", "app", "ai", "companion", "engine", "store",
            "result", "local", "url", "name", "vip", "troubleshoot",
            // positive events — let them be celebrated directly
            "great day", "good day", "wonderful day", "happy today",
            "прекрасный день", "хороший день", "замечательный день",
            // dance / movement
            "dance", "танцевать", "потанцуем",
            // birthday
            "birthday", "день рождения",
            // missing someone
            "i miss", "я скучаю",
            // paranoia / fear
            "someone is watching", "за мной следят", "в доме чужой",
            // leave me alone
            "leave me alone", "go away", "оставь меня", "уйди"
        )
    }

    // Conversation context
    private var lastUserMessage: String? = null
    private var lastAIReply: String? = null
    private var lastCheckInDay: Int = -1
    private val recentTopics: ArrayDeque<String> = ArrayDeque()
    private val recentMoods: ArrayDeque<String> = ArrayDeque()
    private var lastReminderDay: Int = -1
    private var lastInteractionTime: Long = 0L

    // Persistent memory (name + facts). Lazily bound to a Context so it survives restarts and
    // the hands-free service building a fresh engine each turn. See [UserMemory].
    private var memory: UserMemory? = null
    private fun memory(context: Context?): UserMemory {
        val existing = memory
        // Rebind if we now have a real Context but were created without one (or vice versa).
        if (existing == null) {
            return UserMemory(context).also { memory = it }
        }
        return existing
    }

    fun resetMemory() {
        lastUserMessage = null
        lastAIReply = null
        lastCheckInDay = -1
        recentTopics.clear()
        recentMoods.clear()
        lastInteractionTime = 0L
    }

    fun replyTo(message: String, caregiverSettings: CaregiverSettings, context: Context? = null, recentConversation: String = ""): CompanionReply {
        // Seed conversation context from history. The hands-free service creates a fresh
        // CompanionEngine each turn, which wipes lastAIReply and breaks follow-up logic.
        // Parsing the conversation string restores it so the engine always knows what it just said.
        if (recentConversation.isNotBlank()) {
            val lines = recentConversation.lines().filter { it.isNotBlank() }
            lines.lastOrNull { it.startsWith("Companion: ") }
                ?.removePrefix("Companion: ")
                ?.also { lastAIReply = it }
            lines.dropLast(1).lastOrNull { it.startsWith("Mom: ") }
                ?.removePrefix("Mom: ")
                ?.also { lastUserMessage = it }
        }

        // Track topic and mood (store up to 5 recent)
        val lowerMsg = message.lowercase(Locale.getDefault())
        when {
            lowerMsg.contains("water") || lowerMsg.contains("drink") -> recentTopics.addLast("hydration")
            lowerMsg.contains("medication") || lowerMsg.contains("medicine") || lowerMsg.contains("лекарство") -> recentTopics.addLast("medication")
            lowerMsg.contains("food") || lowerMsg.contains("eat") || lowerMsg.contains("еда") -> recentTopics.addLast("food")
        }
        if (recentTopics.size > 5) recentTopics.removeFirst()
        when {
            lowerMsg.contains("sad") || lowerMsg.contains("грустно") || lowerMsg.contains("lonely") || lowerMsg.contains("одиноко") -> recentMoods.addLast("sad")
            lowerMsg.contains("happy") || lowerMsg.contains("счастливо") || lowerMsg.contains("good") || lowerMsg.contains("хорошо") -> recentMoods.addLast("happy")
        }
        if (recentMoods.size > 5) recentMoods.removeFirst()

        // Update last interaction time
        lastInteractionTime = System.currentTimeMillis()

        // Proactive care: hydration/medication reminders once per day
        if (context != null) {
            val prefs = context.getSharedPreferences("companion_engine", android.content.Context.MODE_PRIVATE)
            val today = java.util.Calendar.getInstance().get(java.util.Calendar.DAY_OF_YEAR)
            val lastRem = prefs.getInt("last_reminder_day", -1)
            if (lastRem != today) {
                prefs.edit().putInt("last_reminder_day", today).apply()
                // Only remind if not already talking about hydration/medication
                if (!recentTopics.contains("hydration") && !recentTopics.contains("medication")) {
                    val lang = if (lowerMsg.contains("как") || lowerMsg.contains("дела") || lowerMsg.contains("вода") || lowerMsg.contains("лекарство")) "ru" else "en"
                    return CompanionReply(if (lang == "ru") "Не забывайте пить воду и принимать лекарства вовремя!" else "Don’t forget to drink water and take your medication on time!")
                }
            }

            // Inactivity-based reminder: if no interaction for 4+ hours
            val lastActive = prefs.getLong("last_interaction_time", 0L)
            val now = System.currentTimeMillis()
            if (lastActive > 0 && now - lastActive > 4 * 60 * 60 * 1000) {
                prefs.edit().putLong("last_interaction_time", now).apply()
                val lang = if (lowerMsg.contains("как") || lowerMsg.contains("дела")) "ru" else "en"
                return CompanionReply(if (lang == "ru") "Я давно не слышала вас. Всё ли хорошо?" else "I haven’t heard from you in a while. Is everything okay?")
            } else {
                prefs.edit().putLong("last_interaction_time", now).apply()
            }
        }
        // Save last user message
        lastUserMessage = message

        // Daily check-in logic (if context provided): on the first interaction of a new day,
        // greet Mom with a wellbeing check-in — unless she's already opening with one of the
        // topics/commands in CHECKIN_SKIP_KEYWORDS, in which case that takes priority instead.
        if (context != null) {
            val prefs = context.getSharedPreferences("companion_engine", android.content.Context.MODE_PRIVATE)
            val today = java.util.Calendar.getInstance().get(java.util.Calendar.DAY_OF_YEAR)
            val lastCheck = prefs.getInt("last_checkin_day", -1)
            if (lastCheck != today) {
                prefs.edit().putInt("last_checkin_day", today).apply()
                val skipsCheckin = CHECKIN_SKIP_KEYWORDS.any { lowerMsg.contains(it) }
                if (!skipsCheckin) {
                    val isRu = lowerMsg.isLikelyRussian()
                    val hour = java.util.Calendar.getInstance().get(java.util.Calendar.HOUR_OF_DAY)
                    val checkinText = when {
                        hour < 10 -> if (isRu)
                            listOf(
                                "Доброе утро! Как вы себя чувствуете? Выпейте воды и не забудьте про лекарства.",
                                "С добрым утром! Как прошла ночь? Не забудьте попить водички.",
                                "Доброе утро! Рада вас слышать. Как вы сегодня?"
                            ).random()
                        else
                            listOf(
                                "Good morning! How are you feeling today? Remember to drink some water.",
                                "Good morning! How did you sleep? Don’t forget your medication.",
                                "Good morning! It’s lovely to hear from you. How are you feeling?"
                            ).random()
                        hour < 14 -> if (isRu)
                            listOf(
                                "Добрый день! Как у вас дела? Вы уже поели сегодня?",
                                "Добрый день! Как прошло утро? Не забудьте про воду и лекарства.",
                                "Добрый день! Рада слышать вас. Как настроение?"
                            ).random()
                        else
                            listOf(
                                "Good afternoon! How are you doing? Have you eaten today?",
                                "Good afternoon! How was your morning? Don’t forget your water.",
                                "Good afternoon! So glad to hear from you. How are you feeling?"
                            ).random()
                        hour < 19 -> if (isRu)
                            listOf(
                                "Добрый вечер! Как прошёл ваш день? Надеюсь, было что-то хорошее.",
                                "Вечер добрый! Как вы себя чувствуете? Выпейте чаю и отдохните немного.",
                                "Добрый вечер! Рада вас слышать. Расскажите, как прошёл день?"
                            ).random()
                        else
                            listOf(
                                "Good evening! How has your day been? I hope something nice happened.",
                                "Good evening! How are you feeling now? Perhaps some tea and a rest?",
                                "Good evening! So glad you reached out. Tell me about your day."
                            ).random()
                        else -> if (isRu)
                            listOf(
                                "Вечер добрый! Уже поздно — как вы себя чувствуете? Скоро пора отдыхать.",
                                "Добрый вечер! Как вы? Надеюсь, день был спокойным и добрым.",
                                "Добрый вечер! Рада вас слышать перед сном. Как вы сегодня?"
                            ).random()
                        else
                            listOf(
                                "Good evening! It’s getting late — how are you feeling? Rest will be good soon.",
                                "Good evening! How are you? I hope your day was peaceful.",
                                "Good evening! It’s nice to hear from you before the day ends. How are you?"
                            ).random()
                    }
                    return CompanionReply(checkinText)
                }
            }
        }
        // Repeat last AI reply if asked
        if (lowerMsg.contains("repeat")) {
            if (lastAIReply != null) return CompanionReply(lastAIReply!!)
        }

        // "Pardon? / I didn't hear" — repeat last reply; fall back to warm prompt
        if (lowerMsg.containsAny(
                "pardon", "say again", "what did you say", "i didn't hear you",
                "i didn't catch that", "didn't hear",
                "не расслышала", "не слышу вас", "что вы сказали",
                "не поняла", "что ты говоришь", "не расслышала вас"
            )) {
            if (lastAIReply != null) return CompanionReply(lastAIReply!!)
            val isRu = lowerMsg.isLikelyRussian()
            return CompanionReply(if (isRu) "Пожалуйста, скажите мне снова — я слушаю внимательно." else "Of course! Please say that again — I'm listening carefully.")
        }

        // Adaptive reply: if user is sad, offer encouragement (only once per sad event)
        if (recentMoods.isNotEmpty() && recentMoods.last() == "sad") {
            val text = if (lowerMsg.isLikelyRussian()) {
                "Я здесь с вами. Всё будет хорошо. Хотите рассказать, что вас тревожит?"
            } else {
                "I'm here with you. Everything will be okay. Want to tell me what's on your mind?"
            }
            recentMoods.removeLast()
            return applyCaregiverHints(CompanionReply(text), caregiverSettings)
        }

        // Custom prompt topics: if user mentions a topic from caregiver settings, respond with a personalized message
        val topics = caregiverSettings.promptTopics.split('\n').map { it.trim() }.filter { it.isNotEmpty() }
        for (topic in topics) {
            if (lowerMsg.contains(topic.lowercase())) {
                val text = if (lowerMsg.isLikelyRussian()) {
                    "Вы упомянули тему: $topic. Это очень интересно! Хотите рассказать больше?"
                } else {
                    "You mentioned: $topic. That's a great topic! Want to tell me more?"
                }
                return applyCaregiverHints(CompanionReply(text), caregiverSettings)
            }
        }

        // Entertain or ask questions if prompted
        val lower = message.lowercase(Locale.getDefault())
        val lowerIsRussian = lower.isLikelyRussian()

        // Hard dangers (suicidal ideation, fire/gas, life-threatening emergency, scam) pre-empt
        // EVERYTHING — including the conversational handlers in handleLowerScope. A non-escalating
        // "you sound tired" handler must never swallow "I want to die" before it can alert a
        // caregiver. Safety first, conversation second.
        hardSafetyReplyFor(message, caregiverSettings)?.let { return it }

        // Persistent memory: capture/recall the user's name and facts ("my name is…",
        // "what's my name", "remember that…", "what do you remember"). Runs before the generic
        // handlers so these never fall through to a vague "tell me more".
        memoryReplyFor(message, context)?.let { return it }

        // Conversation follow-up: if the AI just asked a question, the user's reply is an
        // ANSWER to that question — not a standalone statement. Without this, a reply of
        // "winter" to "What's your favourite season?" fires no handler and falls through to
        // the generic "I hear you, tell me more" fallback, which feels random and broken.
        followUpReplyFor(message, lower, lowerIsRussian)?.let { return it }

        handleLowerScope(lower, lowerIsRussian)?.let { return it }

        val normalized = message.lowercase(Locale.getDefault())
        val isRussian = normalized.isLikelyRussian()

        handleNormedA(normalized, isRussian)?.let { return it }
        handleNormedB(normalized, isRussian)?.let { return it }
        handleNormedC(normalized, isRussian)?.let { return it }
        handleNormedC2(normalized, isRussian)?.let { return it }
        handleNormedD(normalized, isRussian)?.let { return it }
        handleNormedE(normalized, isRussian)?.let { return it }
        handleNormedF(normalized, isRussian)?.let { return it }
        handleNormedG(normalized, isRussian)?.let { return it }
        handleNormedH(normalized, isRussian)?.let { return it }
        handleNormedI(normalized, isRussian)?.let { return it }
        handleNormedJ(normalized, isRussian)?.let { return it }
        handleNormedK(normalized, isRussian)?.let { return it }
        handleNormedL(normalized, isRussian)?.let { return it }
        handleNormedM(normalized, isRussian)?.let { return it }
        handleNormedN(normalized, isRussian)?.let { return it }
        handleNormedO(normalized, isRussian)?.let { return it }
        handleNormedP(normalized, isRussian)?.let { return it }
