        HandlersB.handleNormedGGGGGGGGGG(normalized, isRussian)?.let { lastAIReply = it.text; return it }
        HandlersB.handleNormedHHHHHHHHHH(normalized, isRussian)?.let { lastAIReply = it.text; return it }
        HandlersB.handleNormedIIIIIIIIII(normalized, isRussian)?.let { lastAIReply = it.text; return it }
        HandlersB.handleNormedJJJJJJJJJJ(normalized, isRussian)?.let { lastAIReply = it.text; return it }
        HandlersB.handleNormedKKKKKKKKKK(normalized, isRussian)?.let { lastAIReply = it.text; return it }
