        if (lower.contains("music") || lower.contains("музыка") || lower.contains("песня") || lower.contains("song") || lower.contains("спой")
            || lower.containsAny("i want to sing", "sing with me", "sing a song", "let's sing", "i used to sing", "i love to sing", "can you sing", "love singing", "enjoy singing", " singing ")) {
