    // Integrate caregiver rules, profile, and vocabulary for personalized replies
    private fun applyCaregiverHints(reply: CompanionReply, caregiverSettings: CaregiverSettings): CompanionReply {
        val rulesText = "${caregiverSettings.rules} ${caregiverSettings.profileNotes} ${caregiverSettings.vocabularyNotes}".lowercase(Locale.getDefault())
        val isRussian = reply.text.lowercase(Locale.getDefault()).isLikelyRussian()

        // Extract Mom's name from profile notes (line starting with "Name:" or "# Name:")
        val momName = caregiverSettings.profileNotes.lines()
            .firstOrNull { it.trimStart('#', ' ').startsWith("Name:", ignoreCase = true) }
            ?.substringAfter(":")?.trim()?.takeIf { it.isNotBlank() && !it.startsWith("(") }

        val adjustedText = when {
            rulesText.contains("very short") || rulesText.contains("brief") || rulesText.contains("коротко") ->
                reply.text.substringBefore(".") + "."

            rulesText.contains("family loves") ||
                rulesText.contains("remind her i love") ||
                rulesText.contains("семья любит") -> {
                if (isRussian) {
                    "${reply.text} Ваша семья любит вас."
                } else {
                    "${reply.text} Your family loves you."
                }
            }

            rulesText.contains("ask about health") || rulesText.contains("check health") || rulesText.contains("здоровье") -> {
                if (isRussian) {
                    "${reply.text} Как ваше здоровье сегодня?"
                } else {
                    "${reply.text} How is your health today?"
                }
            }

            rulesText.contains("always reassure") || rulesText.contains("always calm") || rulesText.contains("всегда успокаивать") -> {
                if (isRussian) {
                    "${reply.text} Всё хорошо — вы в безопасности."
                } else {
                    "${reply.text} All is well — you are safe."
                }
            }

            rulesText.contains("she is religious") || rulesText.contains("she prays") || rulesText.contains("верующая") -> {
                if (isRussian) {
                    "${reply.text} Храни вас Бог."
                } else {
                    "${reply.text} God bless you."
                }
            }

            // Occasionally personalise greetings with Mom's name (roughly 1 in 4 times)
            momName != null && (0..3).random() == 0 -> {
                val text = reply.text
                // Prepend name as a warm address only when the reply starts with a greeting word
                val startsWithGreeting = text.startsWith("Добр", ignoreCase = true) ||
                    text.startsWith("Привет", ignoreCase = true) ||
                    text.startsWith("Good ", ignoreCase = true) ||
                    text.startsWith("Hello", ignoreCase = true) ||
                    text.startsWith("Hi", ignoreCase = true)
                if (startsWithGreeting) {
                    if (isRussian) "$momName, $text" else "$momName, $text"
                } else text
            }

            else -> reply.text
        }

        return reply.copy(text = adjustedText)

    }

    /**
     * Full safety gate (hard + soft). Kept for [AiClient], which checks safety BEFORE handing a
     * message to a remote AI. Inside [replyTo] we deliberately split this: hard dangers run
     * before the conversational handlers, soft concerns run after, so that mentioning a doctor
     * or feeling "off" doesn't pre-empt a warm, specific reply with a canned disclaimer.
     */
    fun safetyReplyFor(message: String, caregiverSettings: CaregiverSettings): CompanionReply? {
        return hardSafetyReplyFor(message, caregiverSettings)
            ?: softSafetyReplyFor(message, caregiverSettings)
    }

    /** Immediate physical danger or fraud — must pre-empt everything else. */
    fun hardSafetyReplyFor(message: String, caregiverSettings: CaregiverSettings): CompanionReply? {
        val normalized = message.lowercase(Locale.getDefault())
        val isRussian = normalized.isLikelyRussian()

        val text = when {
            // Suicidal ideation (active OR passive death-wish) — highest priority. Respond with
            // warmth, not a cold "call 911" line, but STILL escalate so a caregiver is alerted.
            normalized.isSuicidalIdeation() -> {
                if (isRussian) {
                    "Я очень рада, что вы сказали мне это — спасибо, что доверились. Вы не одни, и то, что вы чувствуете, очень важно для меня. Пожалуйста, прямо сейчас позвоните близкому человеку или на линию доверия. Я остаюсь рядом с вами и никуда не уйду."
                } else {
                    "I'm so glad you told me — thank you for trusting me. You are not alone, and what you're feeling matters deeply to me. Please reach out to someone you trust right now, or call a crisis helpline. I'm staying right here with you and I'm not going anywhere."
                }
            }

            normalized.containsWord(
                "i smell gas", "smell gas", "gas leak", "there's a fire", "something is on fire",
                "i see smoke", "house is on fire",
                "пахнет газом", "утечка газа", "пожар", "что-то горит", "вижу дым", "дом горит",
                "запах дыма", "горит на кухне"
            ) -> {
                if (isRussian) {
                    "НЕМЕДЛЕННО покиньте помещение! Не включайте свет и не пользуйтесь выключателями. Выйдите на улицу и позвоните 112 или попросите кого-то рядом вызвать помощь. УХОДИТЕ СЕЙЧАС!"
                } else {
                    "LEAVE the building immediately! Do NOT switch any lights or use anything electrical. Get outside and call emergency services — or ask someone nearby to call right now. GO NOW!"
                }
            }

            normalized.isEmergency() -> {
                if (isRussian) {
                    "Это звучит срочно. Пожалуйста, позвоните в службу помощи сейчас или попросите кого-то рядом вызвать помощь."
                } else {
                    "That sounds urgent. Please call emergency services now, or ask someone nearby to stay with you and call for help."
                }
            }

            normalized.isPossibleScam() -> {
                if (isRussian) {
                    "Пожалуйста, не говорите пароли, банковские данные, коды или подарочные карты. Давайте остановимся и позвоним человеку, которому вы доверяете."
                } else {
                    "Please do not share passwords, bank information, gift cards, or verification codes. Let's pause and call someone you trust before doing anything with money."
                }
            }

            else -> null
        } ?: return null

        val level = when {
            normalized.isPossibleScam() -> EscalationLevel.SCAM
            else -> EscalationLevel.EMERGENCY
        }

        return applyLocalRuleHints(CompanionReply(text, level), caregiverSettings)
    }

    /** Softer concerns (explicit "call my family", or an unhandled symptom) — fallback only. */
    fun softSafetyReplyFor(message: String, caregiverSettings: CaregiverSettings): CompanionReply? {
        val normalized = message.lowercase(Locale.getDefault())
        val isRussian = normalized.isLikelyRussian()

        val text = when {
            normalized.isContactRequest() -> {
                if (isRussian) {
                    "Хорошо. Давайте позвоним вашему помощнику или семье сейчас."
                } else {
                    "Okay. Let's call your caregiver or family now."
                }
            }

            normalized.isMedicalConcern() -> {
                if (isRussian) {
                    "Я могу быть рядом и помочь подумать о следующем шаге, но я не могу давать медицинские советы. Если это серьезно, новое или страшно, позвоните врачу или близкому человеку."
                } else {
                    "I can stay with you and help you think through the next step, but I cannot give medical advice. If this feels serious, new, or scary, please call your doctor or a trusted person."
                }
            }

            else -> null
        } ?: return null

        return applyLocalRuleHints(CompanionReply(text, EscalationLevel.MEDICAL), caregiverSettings)
    }

    fun escalationLevelForText(text: String): EscalationLevel {
        val normalized = text.lowercase(Locale.getDefault())

        return when {
            normalized.isEmergency() ||
                normalized.isSuicidalIdeation() ||
                normalized.containsAny(
                    "call 911",
                    "emergency services",
                    "urgent help",
                    "emergency room",
                    "службу помощи",
                    "скорая помощь"
                ) -> EscalationLevel.EMERGENCY

            normalized.isPossibleScam() ||
                normalized.containsAny(
                    "do not share",
                    "verification codes",
                    "pause before",
                    "do not send money",
                    "не говорите пароли",
                    "не отправляйте деньги"
                ) -> EscalationLevel.SCAM

            normalized.isContactRequest() ||
                normalized.isMedicalConcern() ||
                normalized.containsAny(
                    "call your caregiver",
                    "call your doctor",
                    "trusted person",
                    "medical advice",
                    "позвоните врачу",
                    "близкому человеку"
                ) -> EscalationLevel.MEDICAL

            else -> EscalationLevel.NONE
        }
    }

    private fun applyLocalRuleHints(
        reply: CompanionReply,
        caregiverSettings: CaregiverSettings
    ): CompanionReply {
        val rulesText = "${caregiverSettings.rules} ${caregiverSettings.profileNotes} ${caregiverSettings.vocabularyNotes}"
            .lowercase(Locale.getDefault())
        val isRussian = reply.text.lowercase(Locale.getDefault()).isLikelyRussian()

        val adjustedText = when {
            rulesText.contains("very short") || rulesText.contains("brief") || rulesText.contains("коротко") ->
                reply.text.substringBefore(".") + "."

            rulesText.contains("family loves") ||
                rulesText.contains("remind her i love") ||
                rulesText.contains("семья любит") -> {
                if (isRussian) {
                    "${reply.text} Ваша семья любит вас."
                } else {
                    "${reply.text} Your family loves you."
                }
            }

            else ->
                reply.text
        }

        return reply.copy(text = adjustedText)
    }

    // Round 7 — 13 new life-situation handlers
    private fun handleNormedF(normalized: String, isRussian: Boolean): CompanionReply? {

        // visitors-cancelled — planned visit fell through; disappointment/loneliness
        if (normalized.containsAny(
