    private fun String.isEmergency(): Boolean {
        return containsWord(
            "can't breathe",
            "cannot breathe",
            "chest pain",
            "heart attack",
            "stroke",
            "i fell",
            "i have fallen",
            "bleeding",
            "suicide",
            "kill myself",
            "danger",
            "i smell gas",
            "gas leak",
            "smell gas",
            "there's a fire",
            "something is on fire",
            "i see smoke",
            "house is on fire",
            "не могу дышать",
            "боль в груди",
            "сердечный приступ",
            "инсульт",
            "я упала",
            "я упал",
            "кровотечение",
            "убить себя",
            "опасность",
            "помогите",      // "help me!" — most common Russian distress call
            "мне плохо",     // "I feel bad/unwell"
            "вызовите скорую", // "call an ambulance"
            "пахнет газом",
            "утечка газа",
            "пожар",
            "что-то горит",
            "вижу дым",
            "дом горит",
            "запах дыма",
            "горит на кухне",
            // Cardiac-suspicious phrasings (chest tightness/pressure, esp. with arm) — voice
            // transcription rarely says the textbook "chest pain".
            "chest feels tight", "chest is tight", "tightness in my chest", "tight in my chest",
            "pressure in my chest", "chest and arm", "arm and chest", "pain down my arm",
            "сдавило грудь", "давит в груди", "тяжесть в груди", "болит грудь",
            "боль в руке и груди", "грудь и рука"
        )
    }

    /**
     * Suicidal ideation — active ("want to die", "kill myself") and passive ("wish I could go to
     * sleep and not wake up", "nobody would miss me"). Escalates EMERGENCY so a caregiver is
     * alerted. Phrases are distinctive enough that substring matching is safe and desirable
     * (we WANT "don't want to live" to match inside a longer sentence).
     */
    private fun String.isSuicidalIdeation(): Boolean {
        // Word-boundary matching: "want to die" must NOT fire inside "want to diet", and bare
        // "not wake up" must NOT fire inside "do not wake up the baby" — those are false alarms.
        return containsWord(
            "want to die", "wanna die", "wish i was dead", "wish i were dead", "kill myself",
            "end my life", "end it all", "take my own life", "don't want to live",
            "dont want to live", "no reason to live", "better off dead", "nothing to live for",
            "don't want to wake up", "dont want to wake up", "and not wake up", "never wake up",
            "nobody would miss me", "no one would miss me", "don't want to be here anymore",
            "dont want to be here anymore", "suicide",
            "не хочу жить", "не хочу больше жить", "лучше бы я умер", "лучше бы я умерла",
            "лучше умереть", "покончить с собой", "свести счёты с жизнью", "не хочу просыпаться",
            "не хочу больше просыпаться", "никому я не нужна больше", "не хочу быть здесь больше",
            "убить себя", "наложить на себя руки"
        )
    }

    private fun String.isPossibleScam(): Boolean {
        // Two-factor scam detection. Mentioning a card/password while chatting ("my grandson gave
        // me a gift card", "I paid with my credit card") is NOT a scam and must not nag/alarm.
        // A real scam = a sensitive item PLUS pressure to give/send/share it (a caller, "they
        // want my…", "asked me to send…"). A few phrasings are unambiguous on their own.

        // Unambiguous — escalate alone.
        if (containsAny(
                "wire money", "western union", "buy gift card", "buy a gift card", "buy gift cards",
                "gift card code", "gift card number", "share my password", "give my password",
                "give them my password", "tell them my password", "read out the code",
                "give them the code", "send the code", "wire transfer", "moneygram",
                "перевести им деньги", "купить подарочную карту", "продиктовать код",
                "сказать код", "сообщить пароль", "назвать пароль", "код из смс", "код из сообщения",
                "просят код", "просит код", "просят деньги", "просит денег", "просят перевести",
                "переведите деньги", "перевести деньги", "переведите на карту", "переведи деньги",
                "назовите код", "продиктуйте код", "код из банка", "звонят из банка", "звонок из банка",
                "просят код и деньги", "требуют деньги", "срочно переведите", "положите деньги на карту"
            )) return true

        // Otherwise require BOTH a sensitive item AND a pressure/coercion context.
        val sensitive = containsWord(
            "gift card", "credit card", "password", "bank account", "bank details",
            "bank information", "card number", "card details", "pin number", "account number",
            "social security", "verification code", "security code", "one time code"
        ) || containsAny(
            "подарочн", "пароль", "номер карты", "данные карты", "банковск", "реквизиты",
            "пин-код", "код подтверждения", "одноразовый код", "кредитн",
            // Bare high-risk terms — a scam still requires a pressure word (checked below),
            // so these do not fire on innocent chat ("у меня нет денег", "потерял карту").
            "код", "деньг", "банк", "карт", "счёт", "счет", "госуслуг", "сбербанк"
        )
        if (!sensitive) return false

        val pressure = containsAny(
            "they want", "they asked", "they told", "they need", "wants me to", "asked me to",
            "told me to", "someone is asking", "someone wants", "asking for my", "wants my",
            "want my", "give them", "give him", "give her", "send them", "share my", "read them",
            "on the phone", "a caller", "stranger", "they keep calling", "wants me to pay",
            "просят", "просит", "требуют", "велели", "сказали отправить", "сказали перевести",
            "хотят чтобы я", "звонят", "незнакомец", "по телефону", "требует", "хотят мой",
            "хотят мои", "просят мой", "просят мои",
            "переведите", "переведи", "перевести", "отправьте", "отправить", "вышлите",
            "назовите", "продиктуйте", "продиктуй", "сообщите", "оплатите", "оплатить",
            "положите на", "звонок из", "звонили из", "позвонили из"
        )
        return pressure
    }

    private fun String.isContactRequest(): Boolean {
        return containsWord(
            "call my caregiver",
            "call my family",
            "call my son",
            "call my daughter",
            "call someone",
            "call for help",
            "позвони",
            "позовите",
            "позови",
            "позвони семье",
            "позвони моему помощнику",
            "нужна помощь",   // "I need help"
            "нужен помощник"  // "I need a helper"
        )
    }

    private fun String.isMedicalConcern(): Boolean {
        // NOTE: this is a soft fallback that runs AFTER the conversational handlers, and it
        // appends a "I can't give medical advice" disclaimer. It must therefore only fire on
        // genuine SYMPTOM words — not on topic words like "doctor"/"medicine"/"врач" (a senior
        // chatting about their doctor-son is not a medical emergency) and not on ambiguous words
        // like "vision" (a dream) or "hearing" (listening). All matching is word-boundary aware.
        return containsWord(
            "pain", "hurts", "ache", "dizzy", "nausea", "nauseous",
            "blood pressure", "heartbeat", "pulse", "swelling", "swollen",
            "rash", "fever", "vomit", "vomiting",
            "blurry vision", "feel faint", "feel weak",
            "больно", "болит", "боль", "болею",
            "кружится голова", "головокружение",
            "тошнит", "тошнота",
            "высокое давление", "низкое давление",
            "слабость", "дрожь", "трясёт",
            "отёк", "опухло", "температура", "жар",
            "одышка", "трудно дышать"
        )
    }

