    private fun String.containsAny(vararg phrases: String): Boolean {
        return phrases.any { contains(it) }
    }

    /**
     * Word-boundary aware match. Unlike [containsAny] (raw substring), this only matches a
     * phrase when it is NOT glued to another letter on either side. This prevents the safety
     * net from firing on accidental substrings — e.g. "pain" inside "Spain", "vision" inside
     * "television", or the Russian "плохо" inside "плохой день" (bad day). Boundaries are
     * Unicode-aware so Cyrillic words are handled correctly. Used by the safety/escalation
     * predicates, where a false positive hijacks the whole conversation into a canned reply.
     */
    private fun String.containsWord(vararg phrases: String): Boolean {
        return phrases.any { phrase ->
            val re = Regex("(?<!\\p{L})" + Regex.escape(phrase) + "(?!\\p{L})")
            re.containsMatchIn(this)
        }
    }

    private fun String.isLikelyRussian(): Boolean {
        return any { it in '\u0400'..'\u04FF' }
    }

    /**
     * Heuristic: does this utterance look like a QUESTION? Used so the generic fallback doesn't
     * answer a question ("how old are you?", "what should I eat?") with a story-prompt like
     * "and what did you think when that happened?" \u2014 which is what made the app feel "stupid".
     * Question words use word boundaries so "what" doesn't match "somewhat", "who" not "whole".
     */
    private fun String.isQuestion(): Boolean {
        if (contains("?")) return true
        return containsWord(
            "what", "what's", "whats", "why", "how", "how's", "where", "where's",
            "when", "who", "whose", "which", "can you", "could you", "would you",
            "do you", "are you", "is it", "will it", "will i", "should i", "is there",
            "\u0447\u0442\u043E", "\u043F\u043E\u0447\u0435\u043C\u0443", "\u0437\u0430\u0447\u0435\u043C", "\u043A\u0430\u043A", "\u0433\u0434\u0435", "\u043A\u043E\u0433\u0434\u0430", "\u043A\u0442\u043E",
            "\u043A\u0430\u043A\u043E\u0439", "\u043A\u0430\u043A\u0430\u044F", "\u043A\u0430\u043A\u043E\u0435", "\u0441\u043A\u043E\u043B\u044C\u043A\u043E", "\u043C\u043E\u0436\u043D\u043E", "\u043C\u043E\u0436\u0435\u0448\u044C", "\u0431\u0443\u0434\u0435\u0442 \u043B\u0438", "\u0435\u0441\u0442\u044C \u043B\u0438"
        )
    }
}
